CREATE TABLE IF NOT EXISTS admins ( id INT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(50) UNIQUE NOT NULL, password VARCHAR(255) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP );
CREATE TABLE IF NOT EXISTS providers ( id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, active TINYINT(1) NOT NULL DEFAULT 1, sort INT NOT NULL DEFAULT 0, image VARCHAR(255) NULL );
CREATE TABLE IF NOT EXISTS appointments ( id INT AUTO_INCREMENT PRIMARY KEY, provider_id INT NOT NULL, full_name VARCHAR(120) NOT NULL, gender VARCHAR(10) NOT NULL, birth VARCHAR(20) NOT NULL, phone VARCHAR(40) NOT NULL, email VARCHAR(120) NULL, note TEXT NULL, app_date DATE NOT NULL, app_time VARCHAR(5) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'new', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, reminder_sent TINYINT(1) NOT NULL DEFAULT 0, CONSTRAINT fk_appt_provider FOREIGN KEY (provider_id) REFERENCES providers(id) ON DELETE CASCADE );
CREATE TABLE IF NOT EXISTS provider_rules ( id INT AUTO_INCREMENT PRIMARY KEY, provider_id INT NOT NULL, type ENUM('closed','open') NOT NULL DEFAULT 'closed', repeat_weekly TINYINT(1) NOT NULL DEFAULT 0, weekday TINYINT NULL, date DATE NULL, start_time VARCHAR(5) NULL, end_time VARCHAR(5) NULL, FOREIGN KEY (provider_id) REFERENCES providers(id) ON DELETE CASCADE );
CREATE TABLE IF NOT EXISTS settings (`key` VARCHAR(100) PRIMARY KEY, `value` TEXT NOT NULL);
